-- ============================================================
-- UKBI Guru: Menulis (8) + Berbicara (7) constructed response
-- Target seksi: MENULIS 8, BERBICARA 7 (set-001 5+5 + set-002 3+2)
-- Idempoten: jalankan di Supabase SQL Editor, ulangi aman (upsert by id).
-- Kolom options berisi {instruction, rubric, scoringMode,
--   sampleExpectedResponse} sesuai seed-ukbi-lean-bank.ts.
-- ============================================================

INSERT INTO "UKBIQuestion"
  ("id", "seksi", "text", "audioUrl", "imageUrl", "passage", "type",
   "options", "correctAnswer", "explanation", "difficulty", "cognitive",
   "domain", "passageType", "wordCount", "keywords", "isActive",
   "isVerified", "uploaderId", "createdAt", "updatedAt", "tingkat")
VALUES
  ('BC-UKBI-GURU-MENULIS-UNGGUL-SET001-Q001', 'MENULIS'::"UKBISeksi", 'Anda adalah guru bahasa Indonesia kelas IX. Tulislah tujuan pembelajaran (indikator pencapaian kompetensi) untuk materi ''Menyusun Teks Pidato Persuasif'' dengan ketentuan: (1) tujuan pembelajaran dirumuskan menggunakan kata kerja operasional yang tepat, (2) mencakup aspek pengetahuan dan keterampilan, (3) sesuai dengan tingkat perkembangan siswa kelas IX. Tuliskan dalam bentuk paragraf yang padu dan jelas.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Ketepatan perumusan tujuan pembelajaran", "weight": 30, "description": "Tujuan dirumuskan dengan kata kerja operasional yang sesuai (misal: mengidentifikasi, menyusun, mempresentasikan)"}, {"criteria": "Kesesuaian aspek pengetahuan dan keterampilan", "weight": 25, "description": "Tujuan mencakup aspek kognitif dan psikomotorik secara seimbang"}, {"criteria": "Kesesuaian dengan tingkat perkembangan siswa", "weight": 20, "description": "Tujuan sesuai dengan kompetensi yang diharapkan untuk kelas IX"}, {"criteria": "Penggunaan bahasa Indonesia yang baik", "weight": 25, "description": "Kalimat efektif, ejaan benar, paragraf padu dan kohesif"}], "scoringMode": "rubric", "sampleExpectedResponse": "Pembelajaran teks pidato persuasif di kelas IX bertujuan agar siswa mampu mengidentifikasi struktur dan kaidah kebahasaan teks pidato persuasif melalui membaca contoh-contoh pidato. Selanjutnya, siswa dapat menyusun kerangka teks pidato persuasif sesuai dengan topik yang dipilih dengan memperhatikan struktur yang tepat. Pada tahap akhir, siswa mampu mempresentasikan teks pidato persuasif di depan kelas dengan intonasi, lafal, dan gestur yang sesuai. Tujuan ini dirancang untuk mengembangkan kemampuan berpikir kritis dan keterampilan berkomunikasi siswa secara bertahap."}'::jsonb, '', NULL, 'MEDIUM'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['tujuan-pembelajaran','indikator','teks-pidato'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-SANGAT-UNGGUL-SET001-Q002', 'MENULIS'::"UKBISeksi", 'Cermati teks akademik berikut yang belum efektif:

"Pembelajaran berbasis proyek ini adalah suatu model pembelajaran yang mana di dalamnya siswa dapat belajar sambil melakukan proyek-proyek nyata yang ada hubungannya dengan kehidupan sehari-hari mereka, sehingga dengan demikian siswa bisa mendapatkan pengalaman belajar yang lebih bermakna dan juga bisa mengembangkan berbagai keterampilan yang mereka butuhkan."

Tulislah kembali teks tersebut agar menjadi paragraf yang efektif, ringkas, dan jelas. Perbaiki dari segi pilihan kata, struktur kalimat, dan efisiensi bahasa. Jelaskan pula alasan perbaikan yang Anda lakukan dalam bentuk catatan singkat di akhir paragraf.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Ketepatan revisi kalimat", "weight": 30, "description": "Menghilangkan pemborosan kata tanpa menghilangkan informasi penting"}, {"criteria": "Pilihan kata dan istilah", "weight": 25, "description": "Menggunakan diksi yang tepat, baku, dan efisien"}, {"criteria": "Keterpaduan paragraf", "weight": 25, "description": "Paragraf kohesif, kalimat padu, dan alur logis"}, {"criteria": "Kualitas catatan alasan revisi", "weight": 20, "description": "Catatan singkat menjelaskan secara tepat alasan perubahan yang dilakukan"}], "scoringMode": "rubric", "sampleExpectedResponse": "Pembelajaran berbasis proyek adalah model yang menghubungkan siswa dengan proyek nyata sesuai kehidupan sehari-hari. Model ini memberikan pengalaman belajar bermakna dan mengembangkan berbagai keterampilan yang dibutuhkan siswa.\n\nCatatan revisi: Kata ''yang mana'' diganti ''yang'' lebih ringkas. Frasa ''di dalamnya'' dihilangkan karena maknanya sudah tercakup. ''Ada hubungannya dengan'' disederhanakan menjadi ''sesuai''. ''Sehingga dengan demikian'' dan ''bisa'' dihilangkan atau diganti dengan bentuk yang lebih baku. Kata ''juga'' di akhir tidak diperlukan karena makna penambahan sudah tersirat dari struktur kalimat."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'EVALUASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['revisi-teks','kalimat-efektif','akademik'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-MADYA-SET001-Q003', 'MENULIS'::"UKBISeksi", 'Anda akan menilai tugas menulis cerita pendek siswa kelas XI. Buatlah sebuah rubrik penilaian yang mencakup empat kriteria penilaian untuk tugas tersebut. Setiap kriteria harus disertai deskripsi yang jelas tentang apa yang dinilai dan indikator kinerja untuk skor tinggi (sangat baik) dan skor rendah (perlu perbaikan). Tuliskan rubrik dalam bentuk paragraf naratif yang menjelaskan setiap kriteria secara berurutan.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Kelengkapan dan ketepatan kriteria", "weight": 30, "description": "Rubrik mencakup empat kriteria yang relevan dengan penilaian cerpen"}, {"criteria": "Kualitas deskripsi kriteria", "weight": 30, "description": "Setiap kriteria dideskripsikan secara jelas dan operasional"}, {"criteria": "Indikator skor tinggi dan rendah", "weight": 20, "description": "Menyertakan indikator untuk skor sangat baik dan perlu perbaikan"}, {"criteria": "Penggunaan bahasa Indonesia baku", "weight": 20, "description": "Menggunakan bahasa yang baku, jelas, dan mudah dipahami"}], "scoringMode": "rubric", "sampleExpectedResponse": "Rubrik penilaian cerpen ini mencakup empat kriteria. Pertama, kesesuaian isi dengan tema, yang menilai apakah cerita yang ditulis sesuai dengan tema yang ditentukan. Skor tinggi diberikan jika cerita relevan dan mengembangkan tema secara kreatif, sedangkan skor rendah jika cerita menyimpang dari tema. Kedua, struktur cerita, yang mencakup kelengkapan orientasi, komplikasi, dan resolusi. Skor tinggi jika struktur lengkap dan alur berkembang logis. Ketiga, penggunaan bahasa, yang meliputi pilihan kata, gaya bahasa, dan ejaan. Skor tinggi jika diksi tepat dan bervariasi. Keempat, orisinalitas dan kreativitas, yang menilai kebaruan ide dan cara penyampaian cerita. Skor tinggi jika cerita menunjukkan sudut pandang yang unik dan orisinal."}'::jsonb, '', NULL, 'MEDIUM'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['rubrik-penilaian','asesmen','cerpen'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-SANGAT-UNGGUL-SET001-Q004', 'MENULIS'::"UKBISeksi", 'Anda diminta mengembangkan deskripsi materi pembelajaran untuk modul ajar tentang ''Menganalisis Unsur Kebahasaan dalam Teks Argumentasi'' untuk siswa kelas XII. Tulislah deskripsi materi yang mencakup: (1) pengertian dan ciri-ciri teks argumentasi, (2) unsur kebahasaan yang khas dalam teks argumentasi (konjungsi argumentatif, verba mental, istilah teknis, dan adverbia frekuensi), (3) contoh analisis singkat, dan (4) panduan langkah-langkah menganalisis. Gunakan bahasa yang komunikatif, sistematis, dan sesuai untuk siswa SMA.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Kelengkapan komponen materi", "weight": 25, "description": "Mencakup pengertian, ciri, unsur kebahasaan, contoh, dan langkah analisis"}, {"criteria": "Kedalaman dan ketepatan isi", "weight": 25, "description": "Penjelasan akurat, contoh relevan, dan langkah analisis logis"}, {"criteria": "Sistematika penyampaian", "weight": 25, "description": "Materi disusun secara sistematis dan mudah diikuti"}, {"criteria": "Kualitas bahasa dan gaya penyampaian", "weight": 25, "description": "Bahasa komunikatif, baku, dan sesuai untuk siswa SMA"}], "scoringMode": "rubric", "sampleExpectedResponse": "Teks argumentasi adalah karangan yang bertujuan meyakinkan pembaca melalui bukti dan alasan logis. Ciri-cirinya meliputi: adanya pendapat atau tesis, disertai data atau fakta pendukung, dan menggunakan penalaran yang logis. Unsur kebahasaan teks argumentasi meliputi: (a) konjungsi argumentatif seperti ''sebab'', ''oleh karena itu'', ''dengan demikian''; (b) verba mental seperti ''berpendapat'', ''menyimpulkan'', ''meyakini''; (c) istilah teknis sesuai topik; dan (d) adverbia frekuensi seperti ''sering'', ''umumnya''. Contoh: ''Pencemaran udara di perkotaan semakin meningkat. Hal ini disebabkan oleh meningkatnya jumlah kendaraan bermotor. Oleh karena itu, pemerintah perlu mendorong penggunaan transportasi umum.'' Analisis: kalimat pertama adalah tesis, kalimat kedua adalah argumen yang ditandai konjungsi kausal ''disebabkan'', dan kalimat ketiga adalah simpulan. Langkah menganalisis: (1) baca teks secara keseluruhan, (2) identifikasi tesis, (3) temukan argumen dan data pendukung, (4) tandai unsur kebahasaan yang muncul, (5) simpulkan pola argumentasi penulis."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['materi-pembelajaran','teks-argumentasi','unsur-kebahasaan'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-UNGGUL-SET001-Q005', 'MENULIS'::"UKBISeksi", 'Tulislah sebuah refleksi profesional singkat sebagai guru bahasa Indonesia setelah menyelesaikan satu semester pembelajaran. Refleksi Anda harus mencakup: (1) satu strategi pembelajaran yang berhasil dan mengapa berhasil, (2) satu tantangan yang dihadapi dan cara mengatasinya, (3) satu hal yang akan Anda lakukan secara berbeda di semester depan, dan (4) komitmen pengembangan kompetensi diri ke depannya. Gunakan gaya bahasa yang reflektif, jujur, dan profesional.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Kedalaman refleksi", "weight": 30, "description": "Refleksi menunjukkan pemikiran kritis dan introspeksi diri yang jujur"}, {"criteria": "Kelengkapan komponen", "weight": 25, "description": "Mencakup strategi berhasil, tantangan, rencana perubahan, dan komitmen"}, {"criteria": "Kualitas solusi dan rencana tindak lanjut", "weight": 25, "description": "Solusi yang ditawarkan realistis dan rencana perbaikan relevan"}, {"criteria": "Penggunaan bahasa reflektif", "weight": 20, "description": "Gaya bahasa reflektif, personal namun tetap profesional, ejaan benar"}], "scoringMode": "rubric", "sampleExpectedResponse": "Semester ini saya menerapkan strategi menulis jurnal harian selama lima menit di awal pelajaran. Strategi ini berhasil meningkatkan kelancaran menulis siswa karena mengurangi tekanan dan memberikan ruang ekspresi bebas. Siswa yang sebelumnya enggan menulis mulai menunjukkan antusiasme. Tantangan terbesar adalah perbedaan tingkat kemampuan menulis yang cukup ekstrem. Beberapa siswa masih kesulitan menyusun kalimat efektif. Saya mengatasinya dengan memberikan bimbingan individual singkat setiap akhir pekan dan menyediakan bank kalimat sebagai referensi. Semester depan, saya akan mengintegrasikan umpan balik teman sejawat (peer review) dalam proses menulis agar siswa lebih kritis terhadap karya sendiri. Ke depannya, saya berkomitmen untuk mengikuti pelatihan asesmen menulis dan memperbanyak membaca referensi tentang pedagogi menulis kreatif."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'EVALUASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['refleksi-profesional','pengembangan-diri','evaluasi'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-SET002-Q001', 'MENULIS'::"UKBISeksi", 'Anda diminta membuat surat dinas untuk menggantikan jam mengajar. Tulislah sebuah surat resmi yang ditujukan kepada Kepala Sekolah berisi: (1) permohonan izin mengikuti pelatihan sehingga tidak dapat mengajar pada hari tertentu, (2) penjelasan singkat bahwa materi yang ditinggalkan akan dijadwalkan ulang, dan (3) permohonan persetujuan atas jadwal pengganti. Tuliskan dengan format surat dinas yang benar, bahasa formal, dan santun.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Struktur surat dinas", "weight": 30, "description": "Terdapat identitas lembaga, tanggal, alamat penerima, salam pembuka, isi, salam penutup, dan tanda tangan"}, {"criteria": "Kesesuaian maksud dan isi", "weight": 30, "description": "Tujuan permohonan jelas, jadwal pengganti disebutkan secara konkret"}, {"criteria": "Ketepatan bahasa", "weight": 25, "description": "Menggunakan ejaan, pilihan kata, dan kalimat efektif ragam resmi"}, {"criteria": "Kesantunan berbahasa", "weight": 15, "description": "Bernada santun, hormat, dan tidak bertele-tele"}], "scoringMode": "rubric", "sampleExpectedResponse": "Hal: Permohonan Penggantian Jam Mengajar\n\nYth. Bapak Kepala Sekolah\nSMPN 3 Surabaya\nDi tempat\n\nDengan hormat,\n\nSaya yang bertanda tangan di bawah ini, nama Aurora Widhiastuti, S.Pd., guru Bahasa Indonesia SMPN 3 Surabaya, dengan ini mengajukan permohonan izin tidak mengajar pada hari Selasa, 12 Agustus 2026 karena mengikuti pelatihan guru tingkat kota.\n\nMateri yang seharusnya disampaikan pada hari tersebut akan dijadwalkan ulang pada hari Jumat, 15 Agustus 2026, sesuai jadwal yang telah dikoordinasikan bersama wali kelas.\n\nDemikian permohonan ini saya sampaikan. Atas persetujuan Bapak, saya mengucapkan terima kasih.\n\nSurabaya, 10 Agustus 2026\nYang mengajukan,\n\n(Jindah Widhiastuti, S.Pd.)"}'::jsonb, '', NULL, 'MEDIUM'::"Difficulty", 'PENERAPAN'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['surat-dinas','administrasi','surat-resmi'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-SET002-Q002', 'MENULIS'::"UKBISeksi", 'Anda adalah guru kelas VII dan akan membagi siswa ke dalam kelompok diskusi cerita rakyat. Tulislah sebuah instruksi kerja kelompok yang berisi: (1) langkah-langkah membaca dan mengidentifikasi unsur intrinsik cerita, (2) pembagian peran dalam kelompok (moderator, pencatat, penyaji, dan anggota), (3) aturan berdiskusi yang sehat dan menghargai pendapat, serta (4) waktu dan laporan yang harus dikumpulkan. Gunakan kalimat perintah yang jelas dan tidak multitafsir.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Kelengkapan instruksi", "weight": 30, "description": "Memuat keempat komponen: langkah, peran, aturan diskusi, dan target laporan"}, {"criteria": "Kejelasan langkah kerja", "weight": 30, "description": "Urutan langkah logis, mudah diikuti, dan tidak multitafsir"}, {"criteria": "Penggunaan kalimat perintah efektif", "weight": 25, "description": "Kalimat perintah singkat, jelas, memakai kata kerja operasional"}, {"criteria": "Kebahasaan dan kerapian", "weight": 15, "description": "Ejaan benar, paragraf padu, dan mudah dibaca oleh siswa kelas VII"}], "scoringMode": "rubric", "sampleExpectedResponse": "INSTRUKSI KERJA KELOMPOK\nDiskusi Unsur Intrinsik Cerita Rakyat\n\nA. Langkah Kerja\n1. Bacalah cerita yang dibagikan guru secara berkelompok.\n2. Identifikasi latar, tokoh, alur, amanat, dan sudut pandang.\n3. Tuliskan hasilnya pada lembar kerja yang tersedia.\n\nB. Pembagian Peran\n1. Moderator memimpin jalannya diskusi.\n2. Pencatat menuliskan hasil kesepakatan kelompok.\n3. Penyaji mempresentasikan hasil di depan kelas.\n4. Semua anggota wajib memberikan pendapat.\n\nC. Aturan Diskusi\n1. Setiap anggota mendapat kesempatan berbicara.\n2. Gunakan bahasa yang santun; jangan menghakimi.\n3. Tidak memotong pembicaraan teman.\n\nD. Target dan Laporan\nDiskusi berlangsung 30 menit. Hasil dikumpulkan kepada guru paling lambat pada akhir pelajaran dalam bentuk lembar jawaban."}'::jsonb, '', NULL, 'MEDIUM'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['instruksi-kerja','diskusi-kelompok','teks-prosedur'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-MENULIS-SET002-Q003', 'MENULIS'::"UKBISeksi", 'Tuliskan sebuah paragraf argumentasi sebagai pengantar makalah profesional Anda dengan topik: ''Peran Guru Bahasa Indonesia dalam Menumbuhkan Budaya Membaca di Era Digital''. Kemukakan tesis yang jelas, dukung dengan dua argumen yang runtut (mengenai dampak gawai terhadap literasi serta peran guru sebagai model baca), serta tutup dengan simpulan yang konsisten. Gunakan kalimat efektif, kosakata akademik, dan konjungsi yang tepat.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": null, "constraints": null, "rubric": [{"criteria": "Kejelasan tesis dan konsistensi argumen", "weight": 30, "description": "Tesis jelas dan seluruh kalimat mendukung satu garis pemikiran"}, {"criteria": "Kualitas penalaran dan dukungan bukti", "weight": 30, "description": "Argumen masuk akal dan didukung contoh atau pendekatan yang relevan"}, {"criteria": "Kebahasaan akademik", "weight": 25, "description": "Kosakata baku, konjungsi sebab-akibat, dan kalimat efektif"}, {"criteria": "Organisasi penulisan", "weight": 15, "description": "Paragraf berstruktur lengkap: tesis, argumen, dan simpulan yang padu"}], "scoringMode": "rubric", "sampleExpectedResponse": "Di tengah banjir informasi digital, kemampuan membaca kritis siswa justru menghadapi tantangan yang besar. Kemudahan mengakses gawai sering kali mendorong remaja terbiasa mengonsumsi teks pendek dan instan tanpa memahami maksud di baliknya. Saya berpendapat bahwa guru bahasa Indonesia memegang posisi strategis dalam menumbuhkan budaya membaca yang sesungguhnya di era digital.\n\nPertama, guru dapat menjadikan gawai sebagai jembatan literasi, bukan musuh. Alih-alih melarang penggunaan layar, guru bisa mengarahkan siswa membandingkan dua berita dari sumber yang berbeda, atau menelusuri ciri-ciri berita hoaks. Pengalaman ini melatih siswa berpikir kritis sambil menikmati aktivitas membaca. Dengan cara ini, alat digital justru memperkuat, bukan melemahkan, kebiasaan membaca.\n\nKedua, guru menjadi model dan memberi ruang refleksi. Guru yang terang membaca di depan siswa, mengajak mendiskusikan isi buku, dan menanyakan ''mengapa penulis memilih sudut pandang itu'' akan menumbuhkan literasi yang tidak hanya menyerap informasi, tetapi juga membangun pemahaman.\n\nDengan demikian, peran guru bukan sekadar mengajarkan teknik membaca, melainkan menanamkan kompetensi berpikir kritis yang dibutuhkan pada zaman digital. Budaya membaca yang baik berawal dari pembelajaran yang menuntun siswa menjadi pembaca yang cerdas, bukan sekadar pembaca yang cepat."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['artikel-argumentatif','era-digital','budaya-literasi'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-MADYA-SET001-Q001', 'BERBICARA'::"UKBISeksi", 'Bayangkan Anda akan memulai pembelajaran tentang teks deskripsi di kelas VII. Sampaikan pembukaan pelajaran yang mencakup: (1) salam dan sapaan, (2) apersepsi dengan mengaitkan materi dengan pengalaman siswa, (3) penyampaian tujuan pembelajaran secara jelas dan memotivasi, serta (4) gambaran kegiatan pembelajaran yang akan dilakukan. Bicaralah seolah-olah Anda sedang berbicara di depan siswa kelas VII.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Pembukaan pembelajaran di kelas (2-3 menit)", "constraints": null, "rubric": [{"criteria": "Struktur penyampaian", "weight": 25, "description": "Penyampaian runtut: salam, apersepsi, tujuan, gambaran kegiatan"}, {"criteria": "Kemampuan apersepsi dan motivasi", "weight": 25, "description": "Apersepsi relevan dan mampu membangkitkan minat siswa"}, {"criteria": "Kejelasan penyampaian tujuan", "weight": 25, "description": "Tujuan pembelajaran disampaikan dengan bahasa yang mudah dipahami siswa kelas VII"}, {"criteria": "Intonasi, lafal, dan gaya bicara", "weight": 25, "description": "Intonasi sesuai konteks, lafal jelas, dan gaya bicara komunikatif"}], "scoringMode": "rubric", "sampleExpectedResponse": "Assalamualaikum warahmatullahi wabarakatuh. Selamat pagi, anak-anak! Apa kabar kalian hari ini? Semoga semuanya dalam keadaan sehat dan semangat ya. Sebelum kita mulai, coba ingat-ingat, siapa di sini yang pernah berlibur ke pantai atau ke gunung? Wah, banyak sekali! Coba kalian bayangkan, jika kalian diminta menceritakan pengalaman liburan itu kepada teman yang tidak ikut, bagaimana cara kalian menggambarkan pemandangan pantai atau gunung itu agar teman kalian bisa membayangkannya? Nah, hari ini kita akan belajar cara mendeskripsikan sesuatu dengan kata-kata yang hidup dan jelas. Materi kita adalah teks deskripsi. Setelah pembelajaran ini, kalian diharapkan mampu mengidentifikasi ciri-ciri teks deskripsi dan menulis deskripsi singkat tentang objek di sekitar kalian. Kegiatan kita hari ini ada tiga: pertama, kita baca contoh teks deskripsi; kedua, kita diskusikan ciri-cirinya; dan ketiga, kalian akan menulis deskripsi tentang benda favorit kalian. Seru, kan? Baik, mari kita mulai."}'::jsonb, '', NULL, 'MEDIUM'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['pembukaan-pembelajaran','apersepsi','komunikasi-kelas'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-UNGGUL-SET001-Q002', 'BERBICARA'::"UKBISeksi", 'Bayangkan Anda sedang menghadapi orang tua/wali siswa dalam pertemuan orang tua-guru. Orang tua siswa tersebut khawatir karena nilai bahasa Indonesia anak mereka menurun. Sampaikan penjelasan yang: (1) menenangkan kekhawatiran orang tua, (2) menjelaskan hasil asesmen secara objektif dan konstruktif, (3) mengidentifikasi faktor penyebab dan area yang perlu diperbaiki, serta (4) memberikan saran konkret yang dapat dilakukan orang tua di rumah untuk membantu anak. Gunakan bahasa yang santun, empatik, dan profesional.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Menjelaskan hasil asesmen kepada orang tua (3-4 menit)", "constraints": null, "rubric": [{"criteria": "Empati dan kemampuan menenangkan", "weight": 20, "description": "Mampu menenangkan kekhawatiran orang tua dengan empati"}, {"criteria": "Kejelasan penjelasan hasil asesmen", "weight": 30, "description": "Menjelaskan hasil asesmen secara objektif, jelas, dan konstruktif"}, {"criteria": "Kualitas saran dan rekomendasi", "weight": 30, "description": "Memberikan saran konkret, realistis, dan aplikatif untuk orang tua"}, {"criteria": "Kesantunan dan profesionalisme", "weight": 20, "description": "Menggunakan bahasa yang santun, profesional, dan mudah dipahami"}], "scoringMode": "rubric", "sampleExpectedResponse": "Selamat siang, Bapak/Ibu. Terima kasih sudah meluangkan waktu untuk bertemu hari ini. Saya memahami kekhawatiran Bapak/Ibu mengenai nilai bahasa Indonesia Ananda yang mengalami penurunan di semester ini. Sebelumnya, saya ingin menyampaikan bahwa penurunan nilai ini tidak berarti kemampuan Ananda menurun secara keseluruhan. Berdasarkan hasil asesmen, Ananda masih memiliki pemahaman yang baik dalam aspek membaca dan menyimak. Nilainya masih di atas Kriteria Ketuntasan Minimal untuk kedua aspek tersebut. Namun, untuk aspek menulis, khususnya dalam menyusun teks argumentasi, Ananda masih perlu banyak latihan. Dari hasil analisis saya, faktor utamanya adalah kurangnya penguasaan struktur teks argumentasi dan keterbatasan kosakata akademik. Ananda cenderung menulis dengan gaya bahasa lisan yang kurang formal. Untuk membantu di rumah, Bapak/Ibu bisa mengajak Ananda membaca artikel opini dari koran atau majalah, lalu mendiskusikan isinya. Tanyakan pendapat Ananda tentang topik yang dibahas dan minta ia menuliskan pendapatnya dalam beberapa paragraf. Kegiatan sederhana ini akan sangat membantu memperkaya kosakata dan pemahaman struktur teks argumentasi. Sekolah juga akan memberikan program remedial dan pendampingan khusus. Saya yakin dengan kerja sama kita, Ananda akan menunjukkan peningkatan yang signifikan."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'KREASI'::"CognitiveDimension", 'SOSIAL'::"KommunikasDomain", NULL, NULL, ARRAY['komunikasi-orang-tua','hasil-asesmen','parent-teacher'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-SANGAT-UNGGUL-SET001-Q003', 'BERBICARA'::"UKBISeksi", 'Anda adalah guru yang memberikan umpan balik lisan kepada seorang siswa kelas XI setelah membaca tugas esai argumentatifnya. Esai siswa tersebut memiliki argumen yang kuat tetapi masih lemah dalam hal: (1) struktur paragraf (tidak ada kalimat topik yang jelas), (2) penggunaan bukti pendukung yang kurang spesifik, dan (3) banyak kesalahan ejaan dan tanda baca. Sampaikan umpan balik secara lisan dengan pendekatan sandwich (pujian-saran-pujian) agar siswa tetap termotivasi. Gunakan bahasa yang membangun, spesifik, dan memberikan panduan perbaikan yang jelas.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Umpan balik lisan kepada siswa (3-4 menit)", "constraints": null, "rubric": [{"criteria": "Penerapan pendekatan sandwich", "weight": 25, "description": "Umpan balik diawali pujian, diikuti saran, diakhiri motivasi"}, {"criteria": "Spesifisitas umpan balik", "weight": 30, "description": "Umpan balik merujuk pada aspek spesifik tulisan, bukan komentar umum"}, {"criteria": "Kualitas panduan perbaikan", "weight": 30, "description": "Memberikan panduan konkret dan jelas tentang cara memperbaiki"}, {"criteria": "Nada dan gaya penyampaian", "weight": 15, "description": "Menggunakan nada yang membangun, suportif, dan memotivasi"}], "scoringMode": "rubric", "sampleExpectedResponse": "Selamat, Rina! Saya baru saja selesai membaca esai argumentatif kamu tentang pentingnya literasi digital. Saya sangat terkesan dengan argumen utamanya, terutama poin kamu tentang korelasi antara literasi digital dan kemampuan berpikir kritis. Itu adalah sudut pandang yang orisinal dan relevan. Argumennya kuat dan menunjukkan bahwa kamu benar-benar memahami topik ini. Nah, sekarang saya ingin membahas beberapa hal yang bisa kita tingkatkan bersama agar esai ini semakin baik. Pertama, soal struktur paragraf. Coba perhatikan paragraf kedua kamu. Isinya bagus, tapi tidak ada kalimat topik yang jelas di awal paragraf. Ingat, setiap paragraf argumentasi idealnya dimulai dengan kalimat topik yang menyatakan ide utama paragraf tersebut, lalu diikuti kalimat penjelas dan bukti. Coba kamu revisi dengan menambahkan kalimat topik di awal setiap paragraf. Kedua, bukti pendukung kamu masih terlalu umum. Kamu menyebutkan ''banyak penelitian menunjukkan'', tapi tidak menyebutkan penelitian spesifik. Coba tambahkan data atau kutipan dari sumber yang konkret. Misalnya, sebutkan penelitian dari Kemdikbud atau UNESCO tentang dampak literasi digital. Ketiga, saya temukan beberapa kesalahan ejaan dan tanda baca. Tolong baca ulang dengan teliti, terutama penggunaan huruf kapital di awal kalimat dan tanda titik di akhir kalimat. Kamu bisa gunakan fitur pemeriksa ejaan di pengolah kata untuk membantu. Secara keseluruhan, saya melihat potensi besar dalam esai ini. Dengan sedikit perbaikan pada struktur, bukti yang lebih spesifik, dan pengecekan ejaan, esai ini bisa menjadi sangat bagus. Saya percaya kamu bisa melakukannya. Silakan revisi dan kumpulkan minggu depan, ya."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'EVALUASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['umpan-balik','feedback-lisan','esai-argumentatif'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-UNGGUL-SET001-Q004', 'BERBICARA'::"UKBISeksi", 'Bayangkan Anda memfasilitasi diskusi kelas tentang isi cerpen ''Robohnya Surau Kami'' karya A. A. Navis di kelas XII. Sampaikan pengantar diskusi yang mencakup: (1) pertanyaan pemantik yang merangsang pemikiran kritis siswa, (2) panduan aturan diskusi yang jelas, (3) beberapa pertanyaan lanjutan untuk menggali analisis siswa tentang tokoh, konflik, dan nilai moral, serta (4) ajakan untuk menghubungkan tema cerita dengan kehidupan sehari-hari. Gunakan bahasa yang mendorong partisipasi aktif dan saling menghargai.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Memfasilitasi diskusi sastra (3-4 menit)", "constraints": null, "rubric": [{"criteria": "Kualitas pertanyaan pemantik", "weight": 25, "description": "Pertanyaan pemantik merangsang berpikir kritis dan analitis"}, {"criteria": "Kemampuan memfasilitasi", "weight": 25, "description": "Menyampaikan aturan diskusi, mendorong partisipasi, dan menjaga fokus"}, {"criteria": "Kedalaman pertanyaan analitis", "weight": 30, "description": "Pertanyaan lanjutan menggali aspek tokoh, konflik, nilai, dan relevansi"}, {"criteria": "Keterampilan berbahasa lisan", "weight": 20, "description": "Intonasi, jeda, dan pilihan kata mendukung suasana dialogis"}], "scoringMode": "rubric", "sampleExpectedResponse": "Selamat pagi, teman-teman. Kita sudah sama-sama membaca cerpen ''Robohnya Surau Kami'' karya A. A. Navis. Saya punya satu pertanyaan pemantik untuk memulai diskusi kita hari ini: Menurut kalian, apa sebenarnya yang ''roboh'' dalam cerita ini? Apakah hanya surau sebagai bangunan fisik, atau ada makna lain yang lebih dalam? Pikirkan sejenak, nanti kita bahas bersama. Sebelum diskusi dimulai, mari kita sepakati aturan mainnya. Pertama, setiap pendapat dihargai, tidak ada pendapat yang salah selama didasari argumen. Kedua, jika ingin berbicara, angkat tangan dan tunggu giliran. Ketiga, jika ada teman yang berbicara, dengarkan dengan saksama sebelum menanggapi. Setuju? Baik. Siapa yang ingin menyampaikan pendapat tentang pertanyaan tadi? Pertanyaan lanjutan untuk diskusi kita: Apa yang mendorong tokoh Ajo Sidi untuk bersikap seperti itu? Kemudian, bagaimana pandangan kalian tentang konflik antara Ajo Sidi dan tokoh ''aku''? Nilai moral apa yang bisa kita petik dari cerita ini? Terakhir, mari kita kaitkan dengan kehidupan kita sehari-hari. Di sekitar kita, apakah masih ada orang-orang yang memiliki sikap seperti tokoh dalam cerita ini? Bagaimana seharusnya kita menyikapinya?"}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['diskusi-sastra','fasilitasi','cerpen'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-SANGAT-UNGGUL-SET001-Q005', 'BERBICARA'::"UKBISeksi", 'Bayangkan Anda diminta menyampaikan presentasi singkat dalam forum MGMP Bahasa Indonesia tentang ide pengembangan profesional. Topik presentasi Anda adalah ''Pemanfaatan Portofolio Digital untuk Meningkatkan Kemampuan Menulis Reflektif Siswa''. Sampaikan presentasi yang mencakup: (1) latar belakang atau masalah yang mendasari ide, (2) konsep portofolio digital dan manfaatnya, (3) langkah-langkah implementasi di kelas, dan (4) ajakan untuk berkolaborasi. Gunakan bahasa yang persuasif, jelas, dan meyakinkan sebagai seorang profesional yang akan mempresentasikan idenya kepada rekan sejawat.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Presentasi ide pengembangan profesional (4-5 menit)", "constraints": null, "rubric": [{"criteria": "Kualitas latar belakang dan identifikasi masalah", "weight": 20, "description": "Latar belakang jelas, masalah relevan, dan didasari data atau observasi"}, {"criteria": "Kejelasan konsep dan manfaat", "weight": 25, "description": "Konsep portofolio digital dijelaskan secara jelas beserta manfaatnya"}, {"criteria": "Keterpahaman langkah implementasi", "weight": 30, "description": "Langkah implementasi sistematis, realistis, dan aplikatif di kelas"}, {"criteria": "Kemampuan persuasi dan ajakan kolaborasi", "weight": 25, "description": "Presentasi meyakinkan dan mengajak rekan sejawat berkolaborasi secara konkret"}], "scoringMode": "rubric", "sampleExpectedResponse": "Assalamualaikum dan selamat pagi, rekan-rekan guru hebat. Saya ingin menyampaikan sebuah ide yang saya yakini dapat menjawab tantangan kita bersama: rendahnya kemampuan menulis reflektif siswa. Saya sering mendapati siswa menulis jurnal pembelajaran dengan sangat dangkal, seperti ''Saya belajar teks prosedur'' tanpa refleksi mendalam tentang apa yang mereka pahami dan bagaimana proses belajarnya. Untuk mengatasi hal ini, saya mengusulkan pemanfaatan portofolio digital. Konsepnya sederhana: setiap siswa memiliki laman portofolio daring yang berisi tulisan reflektif mingguan, dilengkapi dengan bukti belajar seperti foto, tautan, atau dokumen. Manfaatnya sangat besar. Pertama, portofolio digital mendorong siswa untuk menulis secara lebih bertanggung jawab karena karyanya dapat dilihat oleh guru dan teman sekelas. Kedua, portofolio digital memudahkan guru melacak perkembangan menulis siswa dari waktu ke waktu. Ketiga, siswa dapat saling memberi umpan balik melalui fitur komentar. Langkah implementasinya: pertama, kita pilih platform yang mudah digunakan, misalnya Google Sites atau Blogspot. Kedua, kita buat rubrik penilaian bersama siswa. Ketiga, kita jadwalkan menulis reflektif setiap hari Jumat selama 20 menit. Keempat, kita lakukan review portofolio setiap akhir bulan dan beri umpan balik. Saya mengajak rekan-rekan untuk mencoba menerapkan ide ini di kelas masing-masing. Mari kita mulai dengan satu kelas dulu, lalu kita evaluasi bersama bulan depan, dan hasilnya bisa kita presentasikan di pertemuan MGMP berikutnya. Saya siap berbagi rubrik dan panduan teknisnya. Siapa yang berminat untuk bergabung dalam kelompok kecil untuk mencoba ini bersama? Terima kasih."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'KREASI'::"CognitiveDimension", 'VOKASIONAL'::"KommunikasDomain", NULL, NULL, ARRAY['presentasi-profesional','portofolio-digital','pengembangan-profesional'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-SET002-Q001', 'BERBICARA'::"UKBISeksi", 'Anda diminta menyampaikan pembinaan singkat kepada siswa yang akan mengikuti lomba menulis cerpen tingkat kota. Sampaikan: (1) semangat dan motivasi awal, (2) tiga strategi menulis cerpen yang efektif (menentukan ide, menyusun konflik, dan menyunting), (3) hal yang harus dihindari saat lomba, serta (4) pesan penutup yang menguatkan. Bicarakan dengan bahasa yang memotivasi, komunikatif, dan mudah dipahami siswa SMP.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Pembinaan siswa lomba menulis cerpen (3-4 menit)", "constraints": null, "rubric": [{"criteria": "Struktur penyampaian", "weight": 25, "description": "Runtut: motivasi, strategi, larangan, pesan penutup"}, {"criteria": "Kualitas strategi yang disampaikan", "weight": 30, "description": "Strategi menulis konkret, aplikatif, dan benar secara konseptual"}, {"criteria": "Kemampuan memotivasi", "weight": 25, "description": "Membangkitkan semangat siswa dengan bahasa yang positif"}, {"criteria": "Intonasi, lafal, dan gaya bicara", "weight": 20, "description": "Intonasi antusias, lafal jelas, dan gaya bicara komunikatif"}], "scoringMode": "rubric", "sampleExpectedResponse": "Selamat pagi, anak-anak calon juara! Saya sangat bangga karena kalian bersedia mewakili sekolah di lomba menulis cerpen tingkat kota. Ingat, kalian menulis bukan hanya untuk menang, tetapi untuk menyampaikan cerita yang kalian miliki.\n\nAda tiga strategi yang akan membantu kalian. Pertama, temukan ide dari hal terdekat: pengalaman, keluarga, atau peristiwa yang kalian amati. Kedua, susun konflik yang kuat — cerpen tanpa konflik ibarat nasi tanpa lauk. Ketiga, sisihkan waktu lima menit terakhir untuk menyunting: periksa ejaan, pilihan kata, dan alur yang sudah kalian tulis.\n\nSebaliknya, hindari dua hal: menulis tema yang belum kalian kuasai, dan terlalu fokus mengejar banyak kata sehingga cerita menjadi bertele-tele. Kualitas, bukan kuantitas.\n\nTerakhir, percaya pada kemampuan kalian. Kalah atau menang, kalian sudah hebat karena berani mencoba. Selamat menulis, dan bawa pulang cerita terbaik kalian!"}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'KREASI'::"CognitiveDimension", 'AKADEMIK'::"KommunikasDomain", NULL, NULL, ARRAY['pembinaan-lomba','menulis-cerpen','motivasi-siswa'], true, true, NULL, now(), now(), 'GURU'::"Tingkat"),
  ('BC-UKBI-GURU-BERBICARA-SET002-Q002', 'BERBICARA'::"UKBISeksi", 'Anda menjadi moderator pada forum Musyawarah Guru Mata Pelajaran (MGMP) Bahasa Indonesia yang membahas rancangan program ''Satu Bulan Satu Buku''. Sampaikan sesi pembukaan yang mencakup: (1) pembukaan dan sapaan kepada peserta, (2) pemaparan latar belakang serta tujuan program, (3) aturan diskusi yang akan dipakai, dan (4) ajakan partisipasi aktif seluruh guru. Sampaikan dengan bahasa yang formal, jelas, dan mampu membangun suasana kolaboratif.', NULL, NULL, NULL, 'CONSTRUCTED', '{"instruction": "Moderator forum MGMP Bahasa Indonesia (2-3 menit)", "constraints": null, "rubric": [{"criteria": "Kemampuan membuka forum", "weight": 25, "description": "Sapaan, latar belakang, dan tujuan program disampaikan runtut dan jelas"}, {"criteria": "Pengelolaan aturan diskusi", "weight": 30, "description": "Aturan diskusi disampaikan konkret, demokratis, dan mudah dipatuhi"}, {"criteria": "Kesantunan dan profesionalisme", "weight": 25, "description": "Bahasa formal santun, menghargai peserta, membangun kolaborasi"}, {"criteria": "Kejelasan dan intonasi", "weight": 20, "description": "Artikulasi jelas, intonasi sesuai, dan alur bicara lancar"}], "scoringMode": "rubric", "sampleExpectedResponse": "Assalamualaikum warahmatullahi wabarakatuh. Salam sejahtera untuk kita semua. Yang saya hormati, Bapak Ibu guru Bahasa Indonesia yang hadir dalam forum MGMP kali ini.\n\nTerima kasih atas kehadiran Bapak Ibu. Forum hari ini bertujuan membahas rancangan program ''Satu Bulan Satu Buku'', yaitu program membaca bersama satu buku setiap bulan untuk menumbuhkan kebiasaan membaca siswa. Kita akan mematangkan konsep, strategi pelaksanaan, dan pembagian peran.\n\nSebelum diskusi dimulai, saya sampaikan beberapa aturan. Pertama, setiap peserta diberi kesempatan berbicara maksimal lima menit. Kedua, masukan disampaikan secara santun, fokus pada substansi, dan tidak menyela pembicara. Ketiga, kesimpulan tiap sesi akan dirangkum oleh notulen dan disepakati bersama.\n\nBapak Ibu yang berbahagia, keberhasilan program ini sangat bergantung pada kontribusi kita semua. Saya mengundang Bapak Ibu untuk menyampaikan pandangan dan pengalaman, baik yang mendukung maupun yang perlu diperbaiki. Marilah kita mulai dari sesi pertama: pemaparan rancangan program. Dipersilakan."}'::jsonb, '', NULL, 'HARD'::"Difficulty", 'EVALUASI'::"CognitiveDimension", 'SOSIAL'::"KommunikasDomain", NULL, NULL, ARRAY['moderator-mgmp','forum-guru','program-membaca'], true, true, NULL, now(), now(), 'GURU'::"Tingkat")
