-- Verifikasi (harus: 8 menulis, 7 berbicara, total 15)
SELECT "seksi", COUNT(*) AS total
FROM "UKBIQuestion"
WHERE "tingkat" = 'GURU' AND "seksi" IN ('MENULIS','BERBICARA') AND "isActive" = true
GROUP BY "seksi" ORDER BY "seksi";

-- ------------------------------------------------------------
-- Pastikan paket "Simulasi UKBI Guru Practice" memakai 5 seksi
-- (Menulis & Berbicara konstruktif) agar layar simulasi
-- menampilkan Seksi IV & V. Idempoten (update by type+title).
