UPDATE "PaketKompetensi"
SET "sections" = '[
  {"name":"Seksi I: Merespons Kaidah","count":10,"seksi":"MERESPONS_KAIDAH","timeLimit":23},
  {"name":"Seksi II: Membaca","count":15,"seksi":"MEMBACA","timeLimit":32},
  {"name":"Seksi III: Mendengarkan","count":5,"seksi":"MENDENGARKAN","timeLimit":14},
  {"name":"Seksi IV: Menulis","count":2,"seksi":"MENULIS","timeLimit":14},
  {"name":"Seksi V: Berbicara","count":2,"seksi":"BERBICARA","timeLimit":9}
]'::jsonb,
    "sectionsData" = '[
  {"name":"Seksi I: Merespons Kaidah","count":10,"seksi":"MERESPONS_KAIDAH","timeLimit":23},
  {"name":"Seksi II: Membaca","count":15,"seksi":"MEMBACA","timeLimit":32},
  {"name":"Seksi III: Mendengarkan","count":5,"seksi":"MENDENGARKAN","timeLimit":14},
  {"name":"Seksi IV: Menulis","count":2,"seksi":"MENULIS","timeLimit":14},
  {"name":"Seksi V: Berbicara","count":2,"seksi":"BERBICARA","timeLimit":9}
]'::jsonb,
    "totalQuestions" = 34,
    "duration" = 90
WHERE "type" = 'UKBI_GURU_SIMULASI' AND "title" = 'Simulasi UKBI Guru Practice';

-- Verifikasi final: distribusi guru per seksi (target: 45/60/30/8/7)
SELECT "seksi", COUNT(*) AS total
FROM "UKBIQuestion"
WHERE "tingkat" = 'GURU' AND "isActive" = true
GROUP BY "seksi" ORDER BY "seksi";
